import {esc,markdown,published,renderSite} from './render.js';
let content;
async function getContent(){return content??=await fetch('/content/public.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('Nie udało się pobrać treści');return r.json()})}
export function init(){
 document.querySelector('#print-article')?.addEventListener('click',()=>window.print());
 const menu=document.querySelector('.mobile-menu');menu?.addEventListener('click',()=>{const open=document.querySelector('#main-nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});
 document.querySelector('#reading-toggle')?.addEventListener('click',()=>document.body.classList.toggle('reading'));
 const q=document.querySelector('#filter-q'),region=document.querySelector('#filter-region'),cat=document.querySelector('#filter-category');
 if(q){const params=new URLSearchParams(location.search);q.value=params.get('q')||'';if([...region.options].some(x=>x.value===params.get('region')))region.value=params.get('region');const norm=s=>s.toLocaleLowerCase('pl').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l');const filter=()=>{let count=0;document.querySelectorAll('#results [data-search]').forEach(e=>{const visible=norm(e.dataset.search).includes(norm(q.value.trim()))&&(!cat.value||cat.value===e.dataset.category)&&(region.value==='Cała Polska'||e.dataset.region==='Cała Polska'||e.dataset.region===region.value);e.hidden=!visible;if(visible)count++});document.querySelector('#no-results').hidden=count>0;document.querySelector('#result-count').textContent=`Wyniki: ${count}`};q.addEventListener('input',filter);region.addEventListener('change',filter);cat.addEventListener('change',filter);filter()}
 const form=document.querySelector('#listing-form');form?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));const body=`Rodzaj: ${d.type}\nWojewództwo: ${d.region}\nKategoria: ${d.category}\n\n${d.body}\n\nKontakt do publikacji: ${d.contact}\n\nZgłoszenie do redakcji — proszę o weryfikację przed publikacją.`;const href=`mailto:${form.dataset.email}?subject=${encodeURIComponent('Ogłoszenie: '+d.title)}&body=${encodeURIComponent(body)}`;const status=document.querySelector('#listing-status');status.replaceChildren(document.createTextNode('Otworzymy Twój program pocztowy. Wyślij w nim przygotowaną wiadomość. Jeśli się nie otworzy, skopiuj treść i napisz na '+form.dataset.email+'. '));const copy=document.createElement('button');copy.type='button';copy.className='btn outline';copy.textContent='Kopiuj zgłoszenie';copy.onclick=async()=>{try{await navigator.clipboard.writeText(d.title+'\n\n'+body);copy.textContent='Skopiowano'}catch{status.append(document.createTextNode('\n'+body))}};status.append(copy);location.href=href});
 const book=document.querySelector('#book-dialog');let entries=[],index=0;function draw(){const p=entries[index];document.querySelector('#book-content').innerHTML=`<h2>${esc(p.title)}</h2><div class="prose">${markdown(p.body)}</div><a href="/blog/${esc(p.id)}/">Otwórz cały artykuł →</a>`;document.querySelector('#book-content').scrollTop=0;document.querySelector('#book-position').textContent=`${index+1} / ${entries.length}`;document.querySelector('#book-prev').disabled=index===0;document.querySelector('#book-next').disabled=index===entries.length-1}
 document.querySelector('#book-mode')?.addEventListener('click',async e=>{try{entries=published((await getContent()).posts);if(!entries.length)return;index=0;draw();book.showModal()}catch{e.currentTarget.textContent='Nie udało się otworzyć. Spróbuj ponownie.'}});document.querySelector('#book-close')?.addEventListener('click',()=>book.close());document.querySelector('#book-prev')?.addEventListener('click',()=>{if(index>0){index--;draw()}});document.querySelector('#book-next')?.addEventListener('click',()=>{if(index<entries.length-1){index++;draw()}});
}
init();
if(new URLSearchParams(location.search).has('preview')&&window.opener){window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==window.opener||e.data?.type!=='mostpomocy-preview')return;content=e.data.content;document.body.innerHTML=renderSite(content,'/');document.documentElement.style.setProperty('--blue',content.settings.primaryColor);init()});window.opener.postMessage({type:'mostpomocy-preview-ready'},location.origin)}
